actions.script:
import groovy.json.JsonOutput

Map inputParams = [productId: productId, pressureBar: pressureBar, fluidGroup: fluidGroup,
        volumeLiters: volumeLiters, nominalDiameterMm: nominalDiameterMm,
        equipmentType: equipmentType, isAssembly: isAssembly, exclusions: exclusions]

missingInputs = []
if (pressureBar == null) missingInputs.add('pressureBar')
if (fluidGroup == null) missingInputs.add('fluidGroup')
if (volumeLiters == null && nominalDiameterMm == null) missingInputs.add('volumeLiters or nominalDiameterMm')
if (!equipmentType) missingInputs.add('equipmentType')
if (isAssembly == null) missingInputs.add('isAssembly')
if (exclusions == null) missingInputs.add('exclusions (pass an empty list if none apply)')

def runValue = ec.entity.makeValue('moqui.math.MathModelRun')
        .setAll([mathModelId: 'MM_PED_APPLICABILITY', startTime: ec.user.nowTimestamp,
                 parameters: JsonOutput.toJson(inputParams), hasError: 'N'])
runValue.setSequencedIdPrimary()
runValue.create()
mathModelRunId = runValue.mathModelRunId

try {
    if (missingInputs) {
        outcome = 'INCOMPLETE'
        ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
                .setAll([endDate: ec.user.nowTimestamp,
                         results: JsonOutput.toJson([outcome: outcome, missingInputs: missingInputs])])
                .update()
        return
    }

    // Article 1.3 real exclusions (subset - full list is longer, out of scope here)
    boolean excluded = exclusions.contains('TransportablePressureEquipment') || exclusions.contains('SimplePressureVessel')
    // Article 1.2: PS > 0.5 bar
    boolean overThreshold = pressureBar > 0.5G
    boolean applicable = overThreshold && !excluded
    outcome = applicable ? 'Applicable' : 'NotApplicable'
    String reason = excluded ? "Excluded under Article 1.3: ${exclusions.find { it in ['TransportablePressureEquipment', 'SimplePressureVessel'] }}"
            : (overThreshold ? 'PS > 0.5 bar (Article 1.2), no applicable exclusion' : 'PS <= 0.5 bar (Article 1.2 threshold not met)')

    String applicableFeatureId = applicable ? 'FEAT_PED_APPLICABLE' : 'FEAT_PED_NOT_APPLICABLE'
    String otherFeatureId = applicable ? 'FEAT_PED_NOT_APPLICABLE' : 'FEAT_PED_APPLICABLE'

    // Idempotency / conflict avoidance: close out any stale appl on the OTHER
    // mutually-exclusive feature before writing the new one, so a re-run with
    // changed inputs never leaves both TRUE and FALSE active at once.
    ec.entity.find('mantle.product.feature.ProductFeatureAppl')
            .condition('productId', productId).condition('productFeatureId', otherFeatureId)
            .conditionDate('fromDate', 'thruDate', ec.user.nowTimestamp)
            .list().each { it.set('thruDate', ec.user.nowTimestamp); it.update() }

    def existingAppl = ec.entity.find('mantle.product.feature.ProductFeatureAppl')
            .condition('productId', productId).condition('productFeatureId', applicableFeatureId)
            .conditionDate('fromDate', 'thruDate', ec.user.nowTimestamp)
            .list()
    if (!existingAppl) {
        ec.entity.makeValue('mantle.product.feature.ProductFeatureAppl')
                .setAll([productId: productId, productFeatureId: applicableFeatureId,
                         fromDate: ec.user.nowTimestamp, applTypeEnumId: 'PfatStandard',
                         evidenceKindEnumId: 'PfekDerived', mathModelRunId: mathModelRunId])
                .create()
    }

    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp,
                     results: JsonOutput.toJson([outcome: outcome, reason: reason, productFeatureId: applicableFeatureId])])
            .update()
} catch (Throwable t) {
    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, hasError: 'Y', errors: t.toString()])
            .update()
    throw t
}
